export const LFF_TEMPLATE_VARIANT_COUNT = MATRIX.length;
export const LFF_MODEL_PRICES = {"Camisa infantil":"15.99","Sudadera":"29.99","Camisa hombre":"19.99","Camisa mujer":"19.99","Top":"19.99","Crop top":"19.99","Taza":"15.00"};

export function normalizeSkuPrefix(value, fallback = "LFF") {
  const cleaned = String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 24);
  return cleaned || fallback;
}

export function buildLffProductTemplate({ title, skuPrefix, vendor = "La Fábrica Friki", descriptionHtml = "", tags = [] }) {
  const prefix = normalizeSkuPrefix(skuPrefix || title, "LFF");
  const modelValues = LFF_TEMPLATE_MODELS.map((item) => ({ name: item.name }));
  const colors = [];
  const sizes = [];
  for (const row of MATRIX) {
    if (!colors.includes(row[2])) colors.push(row[2]);
    if (!sizes.includes(row[3])) sizes.push(row[3]);
  }
  return {
    title: String(title || "").trim(),
    descriptionHtml: String(descriptionHtml || ""),
    vendor: String(vendor || "La Fábrica Friki").trim(),
    productType: "Merchandising LFF",
    tags: Array.isArray(tags) ? tags : [],
    status: "DRAFT",
    productOptions: [
      { name: "Modelo", position: 1, values: modelValues },
      { name: "Color", position: 2, values: colors.map((name) => ({ name })) },
      { name: "Talla", position: 3, values: sizes.map((name) => ({ name })) },
    ],
    variants: MATRIX.map(([modelCode, model, color, size, skuTail]) => ({
      optionValues: [
        { optionName: "Modelo", name: model },
        { optionName: "Color", name: color },
        { optionName: "Talla", name: size },
      ],
      price: LFF_MODEL_PRICES[model] || "19.99",
      sku: `${prefix}-${skuTail}`,
      taxable: true,
      inventoryPolicy: "CONTINUE",
    })),
  };
}


