export function buildLffMugProductTemplate({ title, skuPrefix, vendor = "La Fábrica Friki", descriptionHtml = "", tags = [] }) {
  const prefix = normalizeSkuPrefix(skuPrefix || title, "LFF-TAZA");
  return {
    title: String(title || "").trim(),
    descriptionHtml: String(descriptionHtml || ""),
    vendor: String(vendor || "La Fábrica Friki").trim(),
    productType: "Taza personalizada LFF",
    tags: Array.isArray(tags) ? tags : [],
    status: "DRAFT",
    productOptions: [
      { name: "Modelo", position: 1, values: [{ name: "Taza" }] },
      { name: "Color", position: 2, values: LFF_MUG_COLORS.map(({ name }) => ({ name })) },
      { name: "Talla", position: 3, values: [{ name: "Única" }] },
    ],
    variants: LFF_MUG_COLORS.map(({ name, code }) => ({
      optionValues: [
        { optionName: "Modelo", name: "Taza" },
        { optionName: "Color", name },
        { optionName: "Talla", name: "Única" },
      ],
      price: "15.00",
      sku: `${prefix}-MUG-${code}`,
      taxable: true,
      inventoryPolicy: "CONTINUE",
    })),
  };
}

